<?php
use App\Http\Controllers\{AuthController,BillingController,BookingController,DashboardController,DemoController,EnquiryController,MarketingController,OnboardingController,PayPalWebhookController,PlatformStatusController,PublicFormController,QuoteController,ServiceController,StaffController};
use Illuminate\Foundation\Auth\EmailVerificationRequest;
use Illuminate\Support\Facades\Route;

Route::view('/', 'marketing.home')->name('home'); Route::get('/pricing',[MarketingController::class,'pricing'])->name('pricing'); Route::view('/faq','marketing.faq')->name('faq'); Route::get('/contact',[MarketingController::class,'contact'])->name('contact'); Route::post('/contact',[MarketingController::class,'sendContact'])->middleware('throttle:public-form')->name('contact.send');
Route::get('/request/{slug}',[PublicFormController::class,'show'])->name('public.enquiry'); Route::post('/request/{slug}',[PublicFormController::class,'store'])->middleware('throttle:public-form')->name('public.enquiry.store'); Route::get('/quote/{token}',[QuoteController::class,'publicShow'])->name('public.quote'); Route::post('/quote/{token}/response',[QuoteController::class,'publicRespond'])->middleware('throttle:public-form')->name('public.quote.respond'); Route::post('/webhooks/paypal',PayPalWebhookController::class)->name('paypal.webhook');
Route::get('/demo', DemoController::class)->middleware('throttle:demo')->name('demo');
Route::middleware('guest')->group(function(){ Route::get('/login',[AuthController::class,'showLogin'])->name('login'); Route::post('/login',[AuthController::class,'login'])->middleware('throttle:6,1'); Route::get('/signup',[AuthController::class,'showRegister'])->name('register'); Route::post('/signup',[AuthController::class,'register'])->middleware('throttle:6,1'); Route::get('/forgot-password',[AuthController::class,'showForgot'])->name('password.request'); Route::post('/forgot-password',[AuthController::class,'sendReset'])->name('password.email'); Route::get('/reset-password/{token}',[AuthController::class,'showReset'])->name('password.reset'); Route::post('/reset-password',[AuthController::class,'reset'])->name('password.update'); });
Route::post('/logout',[AuthController::class,'logout'])->middleware('auth')->name('logout');
Route::middleware('auth')->group(function(){ Route::get('/email/verify',[AuthController::class,'verifyNotice'])->name('verification.notice'); Route::get('/email/verify/{id}/{hash}',function(EmailVerificationRequest $request){$request->fulfill(); return redirect()->route('dashboard');})->middleware('signed')->name('verification.verify'); Route::post('/email/verification-notification',[AuthController::class,'resendVerification'])->middleware('throttle:6,1')->name('verification.send'); });
Route::middleware(['auth','verified','business','demo.readonly'])->group(function(){
 Route::get('/app',DashboardController::class)->name('dashboard'); Route::get('/onboarding',[OnboardingController::class,'show'])->name('onboarding.show'); Route::put('/onboarding',[OnboardingController::class,'update'])->name('onboarding.update'); Route::get('/bookings',[BookingController::class,'index'])->name('bookings.index'); Route::get('/bookings/create/{quote?}',[BookingController::class,'create'])->name('bookings.create'); Route::post('/bookings',[BookingController::class,'store'])->middleware('can:manage-business')->name('bookings.store'); Route::patch('/bookings/{booking}',[BookingController::class,'update'])->name('bookings.update');
 Route::middleware('can:manage-business')->group(function(){ Route::resource('enquiries',EnquiryController::class)->only(['index','create','store','show','update']); Route::get('/enquiries/{enquiry}/quote',[QuoteController::class,'create'])->name('quotes.create'); Route::post('/enquiries/{enquiry}/quote',[QuoteController::class,'store'])->name('quotes.store'); Route::get('/quotes/{quote}',[QuoteController::class,'show'])->name('quotes.show'); Route::post('/quotes/{quote}/approve',[QuoteController::class,'approve'])->name('quotes.approve'); Route::post('/quotes/{quote}/send',[QuoteController::class,'send'])->name('quotes.send'); Route::get('/quotes/{quote}/print',[QuoteController::class,'printable'])->name('quotes.print'); Route::get('/services',[ServiceController::class,'index'])->name('services.index'); Route::post('/services',[ServiceController::class,'store'])->name('services.store'); Route::put('/services/{service}',[ServiceController::class,'update'])->name('services.update'); Route::get('/staff',[StaffController::class,'index'])->name('staff.index'); Route::post('/staff',[StaffController::class,'store'])->name('staff.store'); Route::get('/billing',[BillingController::class,'index'])->name('billing.index'); Route::post('/billing/checkout/{plan}',[BillingController::class,'checkout'])->name('billing.checkout'); Route::get('/billing/return',[BillingController::class,'returned'])->name('billing.return'); Route::post('/billing/cancel',[BillingController::class,'cancel'])->name('billing.cancel'); });
});
Route::get('/platform/status',PlatformStatusController::class)->middleware(['auth','can:view-platform-status'])->name('platform.status');
